import{_ as i,o as s,c as t,a2 as e}from"./chunks/framework.BqNd1sPY.js";const h=JSON.parse('{"title":"D09：一次完整训练循环","description":"","frontmatter":{},"headers":[],"relativePath":"01-14天理论课/D09-一次完整训练循环.md","filePath":"01-14天理论课/D09-一次完整训练循环.md"}'),n={name:"01-14天理论课/D09-一次完整训练循环.md"};function r(l,a,d,p,c,k){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="d09-一次完整训练循环" tabindex="-1">D09：一次完整训练循环 <a class="header-anchor" href="#d09-一次完整训练循环" aria-label="Permalink to &quot;D09：一次完整训练循环&quot;">​</a></h1><h2 id="今日目标" tabindex="-1">今日目标 <a class="header-anchor" href="#今日目标" aria-label="Permalink to &quot;今日目标&quot;">​</a></h2><p>能读懂训练日志，知道何时看训练 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a>、验证 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a>、<a href="/LLMTrain/05-速查表/术语速查#term-gradient" class="wiki-term" data-wiki-title="gradient" data-wiki-summary="loss 对各参数的局部变化率，指出当前附近怎样调整会改变 loss。" data-wiki-misconception="梯度直接给出了全局最优答案。">梯度</a>范数和吞吐。</p><h2 id="训练循环" tabindex="-1">训练循环 <a class="header-anchor" href="#训练循环" aria-label="Permalink to &quot;训练循环&quot;">​</a></h2><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> step </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(max_steps):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    x, y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> next_train_batch()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    optimizer.zero_grad()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    logits, loss </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> model(x, y)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    loss.backward()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    clip_grad_norm_if_needed()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    optimizer.step()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    scheduler.step()</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> step </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> eval_interval </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        evaluate_without_updating_parameters()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        save_checkpoint()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>真实代码还要处理设备、混合精度、分布式同步、随机种子和异常恢复，但主线就是前向、<a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">损失</a>、反向、更新、验证。</p><h2 id="日志怎么读" tabindex="-1">日志怎么读 <a class="header-anchor" href="#日志怎么读" aria-label="Permalink to &quot;日志怎么读&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>step=0   train_loss=4.20 val_loss=4.25</span></span>
<span class="line"><span>step=200 train_loss=2.10 val_loss=2.20</span></span>
<span class="line"><span>step=500 train_loss=1.20 val_loss=2.35</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>前两行说明训练和验证都改善。最后一行训练继续改善而验证变差，是<a href="/LLMTrain/05-速查表/术语速查#term-overfitting" class="wiki-term" data-wiki-title="overfitting" data-wiki-summary="模型继续改善训练数据表现，却不能同步改善未见数据表现的现象。" data-wiki-misconception="训练 loss 下降就一定没有过拟合。">过拟合</a>信号之一，但单次波动不足以下结论，应看重复评测和整体趋势。</p><p>配套分镜：<a href="./../04-图解与数字漫画/训练与验证-两套题">训练与验证：两套题</a></p><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>下一步</th></tr></thead><tbody><tr><td>train/val 都不降</td><td><a href="/LLMTrain/05-速查表/术语速查#term-learning-rate" class="wiki-term" data-wiki-title="learning rate" data-wiki-summary="控制每次参数更新幅度的超参数。" data-wiki-misconception="学习率越大，训练一定越快越好。">学习率</a>、数据、实现或容量问题</td><td>先尝试<a href="/LLMTrain/05-速查表/术语速查#term-overfitting" class="wiki-term" data-wiki-title="overfitting" data-wiki-summary="模型继续改善训练数据表现，却不能同步改善未见数据表现的现象。" data-wiki-misconception="训练 loss 下降就一定没有过拟合。">过拟合</a>一个 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a></td></tr><tr><td>train 降、val 升</td><td><a href="/LLMTrain/05-速查表/术语速查#term-overfitting" class="wiki-term" data-wiki-title="overfitting" data-wiki-summary="模型继续改善训练数据表现，却不能同步改善未见数据表现的现象。" data-wiki-misconception="训练 loss 下降就一定没有过拟合。">过拟合</a>或分布差异</td><td>检查切分、正则化、训练时长</td></tr><tr><td><a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 为 NaN</td><td>数值不稳定、异常数据或过大<a href="/LLMTrain/05-速查表/术语速查#term-learning-rate" class="wiki-term" data-wiki-title="learning rate" data-wiki-summary="控制每次参数更新幅度的超参数。" data-wiki-misconception="学习率越大，训练一定越快越好。">学习率</a></td><td>定位首个异常 <a href="/LLMTrain/05-速查表/术语速查#term-step" class="wiki-term" data-wiki-title="step" data-wiki-summary="本课程默认指一次优化器更新；阅读日志时应先确认工具的定义。" data-wiki-misconception="所有框架里的 step 都代表完全相同的事件。">step</a></td></tr><tr><td>OOM</td><td>激活、<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>或 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a> 超出内存</td><td>先减 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a> 或序列长度</td></tr></tbody></table><h2 id="先过拟合一个-batch" tabindex="-1">先过拟合一个 batch <a class="header-anchor" href="#先过拟合一个-batch" aria-label="Permalink to &quot;先过拟合一个 batch&quot;">​</a></h2><p>这是最有效的训练单元测试之一。让模型反复看同一小批样本，若 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 无法明显下降，应先怀疑数据对齐、遮罩、模型、<a href="/LLMTrain/05-速查表/术语速查#term-gradient" class="wiki-term" data-wiki-title="gradient" data-wiki-summary="loss 对各参数的局部变化率，指出当前附近怎样调整会改变 loss。" data-wiki-misconception="梯度直接给出了全局最优答案。">梯度</a>或<a href="/LLMTrain/05-速查表/术语速查#term-optimizer" class="wiki-term" data-wiki-title="optimizer" data-wiki-summary="根据梯度及内部状态计算参数更新的算法，例如 AdamW。" data-wiki-misconception="优化器负责计算前向预测或损失。">优化器</a>，而不是购买更多数据。</p><p>成功<a href="/LLMTrain/05-速查表/术语速查#term-overfitting" class="wiki-term" data-wiki-title="overfitting" data-wiki-summary="模型继续改善训练数据表现，却不能同步改善未见数据表现的现象。" data-wiki-misconception="训练 loss 下降就一定没有过拟合。">过拟合</a>一个 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a> 只证明管线具备记忆这批数据的能力，不证明泛化。</p><h2 id="梯度累积" tabindex="-1">梯度累积 <a class="header-anchor" href="#梯度累积" aria-label="Permalink to &quot;梯度累积&quot;">​</a></h2><p>显存只能放 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a>=2，但希望每 8 个小 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a> 更新一次，可以累计 8 次<a href="/LLMTrain/05-速查表/术语速查#term-gradient" class="wiki-term" data-wiki-title="gradient" data-wiki-summary="loss 对各参数的局部变化率，指出当前附近怎样调整会改变 loss。" data-wiki-misconception="梯度直接给出了全局最优答案。">梯度</a>，得到有效 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a> 约 16。严格等价还取决于 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 缩放、随机层、归一化、分布式和<a href="/LLMTrain/05-速查表/术语速查#term-optimizer" class="wiki-term" data-wiki-title="optimizer" data-wiki-summary="根据梯度及内部状态计算参数更新的算法，例如 AdamW。" data-wiki-misconception="优化器负责计算前向预测或损失。">优化器</a>细节，所以应称“近似获得更大有效 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a>”，而非无条件完全等价。</p><h2 id="今日验收" tabindex="-1">今日验收 <a class="header-anchor" href="#今日验收" aria-label="Permalink to &quot;今日验收&quot;">​</a></h2><ol><li>为什么验证时不更新<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>？</li><li>train <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 很低而 val <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 很高说明什么？</li><li>单 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a> <a href="/LLMTrain/05-速查表/术语速查#term-overfitting" class="wiki-term" data-wiki-title="overfitting" data-wiki-summary="模型继续改善训练数据表现，却不能同步改善未见数据表现的现象。" data-wiki-misconception="训练 loss 下降就一定没有过拟合。">过拟合</a>能证明什么，不能证明什么？</li><li>减小 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a> 为什么常能缓解 OOM？</li></ol><p>下一课：<a href="./D10-预训练与规模化训练">D10：预训练与规模化训练</a></p>`,19)])])}const o=i(n,[["render",r]]);export{h as __pageData,o as default};
